class Solution:
    def maximumLength(self, s: str) -> int:
        n = len(s)
        max_len = -1

        for length in range(n, 0, -1):  # Iterate from longest possible length down to 1
            char_counts = {}
            
            # Count occurrences of special substrings of current length
            i = 0
            while i <= n - length:
                substring = s[i : i + length]
                
                # Check if the substring is special
                if len(set(substring)) == 1:
                    char = substring[0]
                    char_counts[char] = char_counts.get(char, 0) + 1
                    
                i += 1
            
            # Check if any special substring of this length occurs at least thrice
            for char in char_counts:
                if char_counts[char] >= 3:
                    return length
        
        return max_len
